examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space4) {
    VStack(spacing: theme.spacing.space2) {
        MonarchAvatar(image: nil, name: {{app.name}}, shape: .square, size: .xl, isDecorative: true)
        Text({{app.name}} + " wants to access your account")
            .monarchTextStyle(.heading)
            .foregroundStyle(theme.colors.textDefault)
            .multilineTextAlignment(.center)
            .accessibilityAddTraits(.isHeader)
        Text({{app.domain}}).monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
        if isVerified {
            MonarchBadge("Verified", tone: .success)
        }
    }
    .frame(maxWidth: .infinity)
    MonarchCard {
        ViewThatFits(in: .horizontal) {
            HStack(spacing: theme.spacing.space3) {
                accountSummary
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .fixedSize(horizontal: true, vertical: false)
                    .frame(maxWidth: .infinity, alignment: .leading)
                switchButton
            }
            VStack(alignment: .leading, spacing: theme.spacing.space2) {
                accountSummary
                switchButton
            }
        }
    }
    VStack(alignment: .leading, spacing: theme.spacing.space2) {
        Text({{app.name}} + " will be able to:").monarchTextStyle(.bodyStrong).foregroundStyle(theme.colors.textDefault)
        scopeRow({{scopes.0.kind|case}}, {{scopes.0.label}})
        scopeRow({{scopes.1.kind|case}}, {{scopes.1.label}})
        scopeRow({{scopes.2.kind|case}}, {{scopes.2.label}}, detail: {{scopes.2.description}})
    }
    .frame(maxWidth: .infinity, alignment: .leading)
    HStack(spacing: theme.spacing.space3) {
        MonarchButton("Cancel", variant: .secondary, size: .lg, isLoading: isDenying, fullWidth: true) { decide(allow: false) }
        MonarchButton("Allow", variant: .primary, size: .lg, isLoading: isAllowing, fullWidth: true) { decide(allow: true) }
    }
    .disabled(isAllowing || isDenying)
    Text(policies)
        .monarchTextStyle(.caption)
        .multilineTextAlignment(.center)
        .frame(maxWidth: .infinity)
    Text({{footnote}})
        .monarchTextStyle(.caption)
        .foregroundStyle(theme.colors.textMuted)
        .multilineTextAlignment(.center)
        .frame(maxWidth: .infinity)
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var isAllowing = false
@State private var isDenying = false
private let isVerified = {{app.verified}}
private let privacyURL = URL(string: {{app.privacyUrl}})
private let termsURL = URL(string: {{app.termsUrl}})

private var policies: AttributedString {
    func plain(_ string: String) -> AttributedString {
        var run = AttributedString(string)
        run.foregroundColor = theme.colors.textMuted
        return run
    }
    func link(_ string: String, _ url: URL?) -> AttributedString {
        var run = AttributedString(string)
        run.link = url
        run.foregroundColor = theme.colors.textLink
        run.underlineStyle = .single
        return run
    }
    return plain("Before you continue, read " + {{app.name}} + "\u{2019}s ") + link("privacy policy", privacyURL)
        + plain(" and ") + link("terms", termsURL) + plain(".")
}

private var accountSummary: some View {
    HStack(spacing: theme.spacing.space3) {
        MonarchAvatar(image: nil, name: {{account.name}}, isDecorative: true)
        VStack(alignment: .leading, spacing: theme.spacing.space0_5) {
            Text({{account.name}}).monarchTextStyle(.bodyStrong).foregroundStyle(theme.colors.textDefault)
            Text(verbatim: {{account.email}}).monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
        }
    }
    .accessibilityElement(children: .combine)
}

private var switchButton: some View {
    MonarchButton("Use another account", variant: .ghost, size: .sm) {
        // Show the account picker.
    }
    .fixedSize()
}

private func scopeRow(_ kind: MonarchConsequenceKind, _ label: String, detail: String? = nil) -> some View {
    HStack(alignment: .firstTextBaseline, spacing: theme.spacing.space2) {
        MonarchIcon(systemName: "checkmark", size: .sm)
            .foregroundStyle(kind == .warning ? theme.colors.warningStrong : theme.colors.successStrong)
        VStack(alignment: .leading, spacing: theme.spacing.space0_5) {
            Text(label)
                .monarchTextStyle(kind == .warning ? .bodyStrong : .body)
                .foregroundStyle(theme.colors.textDefault)
                .fixedSize(horizontal: false, vertical: true)
            if let detail {
                Text(detail).monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
            }
        }
        .frame(maxWidth: .infinity, alignment: .leading)
    }
    .frame(maxWidth: .infinity, alignment: .leading)
    .accessibilityElement(children: .ignore)
    .accessibilityLabel((kind == .warning ? "Sensitive: " : "Allowed: ") + label)
}

private func decide(allow: Bool) {
    if allow { isAllowing = true } else { isDenying = true }
    Task {
        // The app grants or refuses the authorization request, then returns to the app's redirect.
        isAllowing = false
        isDenying = false
    }
}

